WITH filtered AS (SELECT id, name, email, country, city, segment, signup_date, is_active, credit_limit, age, SUBSTRING(city, 1, 3) AS city_prefix, UPPER(TRIM(name)) AS name_normalized, COALESCE(city, 'N/A') AS resolved_city FROM customers WHERE city IS NOT NULL), with_windows AS (SELECT *, COUNT(age) OVER (PARTITION BY country, segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_count_age, MIN(age) OVER (PARTITION BY country, segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_age, SUM(age) OVER (PARTITION BY country, segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_age, MAX(age) OVER (PARTITION BY country, segment ORDER BY age, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_age FROM filtered), not_flagged AS (SELECT s.* FROM with_windows s WHERE NOT EXISTS (SELECT 1 FROM sessions ch WHERE ch.customer_id = s.id AND ch.started_at >= s.signup_date)), enriched AS (SELECT id, name, email, country, city, segment, signup_date, is_active, name_normalized, running_count_age, running_sum_age, AVG(credit_limit) OVER (PARTITION BY country ORDER BY signup_date, id ROWS BETWEEN 6 PRECEDING AND 1 PRECEDING) AS credit_limit_avg_6_prior, AVG(running_min_age) OVER w_grp AS running_min_age_avg_6 FROM not_flagged WINDOW w_grp AS (PARTITION BY YEAR(signup_date), country ORDER BY credit_limit, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), valid AS (SELECT id, name, city, segment, signup_date, name_normalized, running_min_age_avg_6, CASE WHEN is_active THEN 'Yes' ELSE 'No' END AS is_active_label, COALESCE(segment, 'NONE') AS segment_clean FROM enriched WHERE segment IS NOT DISTINCT FROM 'Corporate'), enriched_customers AS (SELECT id, city, name_normalized, running_min_age_avg_6, SUM(running_min_age_avg_6) OVER (PARTITION BY segment, city ORDER BY running_min_age_avg_6, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_running_min_age_avg_6, SUM(running_min_age_avg_6) OVER (ORDER BY signup_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_running_min_age_avg_6, NTILE(10) OVER (PARTITION BY city ORDER BY running_min_age_avg_6 DESC, id) AS running_min_age_avg_6_bucket FROM valid), totals AS (SELECT city, COUNT(DISTINCT city) AS distinct_cities, SORT_ARRAY(COLLECT_SET(city)) AS city_list, COUNT(*) FILTER (WHERE city = 'Berlin') AS berlin_rows, COUNT(DISTINCT id) AS distinct_ids FROM enriched_customers GROUP BY city) SELECT city, distinct_ids, CASE WHEN city RLIKE '^(Chiang Mai|New York)$' THEN 'OTHER_ZONE' ELSE 'GROUP_A' END AS city_zone FROM totals ORDER BY distinct_ids DESC, city_zone;
